--cream:#f4f8f0;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--danger:#b23b3b;--danger-soft:#f6e4e2;--teal-soft:#d9ecec}
*{box-sizing:border-box}
.stage{display:flex;gap:28px;flex-wrap:wrap;justify-content:center;padding:24px;background:#edf1ea;font-family:Figtree,'Segoe UI',system-ui,sans-serif;color:var(--ink)}
.phone{width:390px;background:var(--cream);border-radius:28px;overflow:hidden;box-shadow:0 8px 30px rgba(0,0,0,.08);display:flex;flex-direction:column;position:relative}
.cap{width:100%;text-align:center;font-size:13px;color:var(--ink-soft);margin-bottom:-12px}
header{padding:12px 20px 16px}
.hrow{display:flex;justify-content:space-between;align-items:center;gap:12px}
.back{width:44px;height:44px;border-radius:999px;border:1.5px solid var(--line);background:var(--paper);display:flex;align-items:center;justify-content:center;font-size:20px}
.chip{display:inline-flex;align-items:center;gap:8px;border-radius:999px;border:1.5px solid var(--line);background:var(--paper);padding:4px 14px 4px 6px;font-size:13px;font-weight:700}
.chip i{width:28px;height:28px;border-radius:10px;background:var(--primary);color:#fff;font-style:normal;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:12px}
.eyebrow{font-size:12px;font-weight:800;letter-spacing:.14em;color:var(--accent-fg);text-transform:uppercase;margin:14px 0 0}
h1{font-family:'Bricolage Grotesque','Segoe UI',sans-serif;font-size:34px;line-height:1.15;font-weight:800;margin:0}
.sub{color:var(--ink-soft);margin-top:4px}
.banner{margin:0 20px;aspect-ratio:16/7;border-radius:22px;background:linear-gradient(135deg,#6fb6b8,#a9c24f);display:flex;align-items:flex-end;padding:12px;color:#fff;font-weight:700;font-size:12px}
.card{margin:24px 20px 0;border-radius:24px;border:1px solid var(--line);background:var(--paper);padding:16px}
.drow{display:flex;gap:14px;align-items:center}
.badge{width:56px;height:64px;border-radius:18px;background:var(--accent-soft);display:flex;flex-direction:column;align-items:center;justify-content:center}
.badge small{font-size:11px;font-weight:800;letter-spacing:.1em;color:var(--accent-fg);text-transform:uppercase}
.badge b{font-family:'Bricolage Grotesque';font-size:26px;line-height:1}
.ey{font-size:12px;font-weight:800;letter-spacing:.12em;color:var(--ink-soft);text-transform:uppercase;margin:0}
.big{font-weight:700;font-size:16px;margin:0}
.soft{font-size:14px;color:var(--ink-soft);margin:0}
.sep{border-top:1px solid var(--line);margin-top:12px;padding-top:12px}
.link{font-size:14px;font-weight:700;text-decoration:underline;color:var(--ink)}
.actions{display:flex;gap:8px;margin-top:12px}
.ghost{border-radius:999px;border:1.5px solid var(--line);background:transparent;font-weight:700;color:var(--ink-soft);padding:7px 14px;font-size:12px}
.desc{margin:12px 20px 0;font-size:15px;line-height:1.45;color:var(--ink)}
.chatrow{margin:12px 20px 0;display:flex}
.chatbtn{flex:1;min-height:44px;border-radius:999px;border:1.5px solid var(--line);background:var(--paper);font-weight:800;font-size:13px;display:flex;align-items:center;justify-content:center;gap:6px}
section.att{margin:24px 20px 0}
h2{font-family:'Bricolage Grotesque';font-size:22px;font-weight:700;margin:0}
ul.list{list-style:none;margin:12px 0 0;padding:0 14px;border-radius:24px;border:1px solid var(--line);background:var(--paper)}
ul.list>li{padding:12px 0;border-top:1px solid var(--line)}
ul.list>li:first-child{border-top:0}
.person{display:flex;align-items:center;gap:12px}
.av{width:40px;height:40px;border-radius:999px;background:var(--primary-soft);color:var(--primary-fg);font-weight:800;display:flex;align-items:center;justify-content:center}
.role{margin-left:auto;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;background:var(--accent-soft);color:var(--accent-fg);border-radius:999px;padding:3px 9px}
.you{margin-left:auto;font-size:11px;font-weight:800;background:var(--primary-soft);color:var(--primary-fg);border-radius:999px;padding:3px 9px}
.items{margin:4px 0 0 52px}
.it{display:flex;gap:12px;padding:12px 0;border-top:1px solid var(--line);align-items:center;text-decoration:none;color:inherit}
.it:first-child{border-top:0}
.th{width:48px;height:48px;border-radius:12px;background:var(--cream);display:flex;align-items:center;justify-content:center;font-size:20px}
.it small{display:block;font-size:12px;color:var(--ink-soft)}
.mode{margin-left:auto;font-size:11px;font-weight:800;border-radius:999px;padding:3px 9px;background:var(--teal-soft);color:#2f6f71}
.mode.g{background:var(--accent-soft);color:var(--accent-fg)}
.more{min-height:44px;font-size:14px;font-weight:800;color:var(--primary-fg);background:none;border:0;padding:0}
.empty{margin-top:12px;border-radius:20px;border:2px dashed var(--line-strong);padding:14px 16px;font-size:15px;color:var(--ink-soft)}
.merge{margin:24px 20px 0}
.field{width:100%;border-radius:12px;border:1.5px solid var(--line);background:var(--cream);padding:8px 10px;font-size:13px;margin-top:8px}
.primary{border-radius:999px;border:0;background:var(--primary);color:#fff;font-weight:800;padding:10px 14px;font-size:13px}
.danger{border-radius:999px;border:1.5px solid var(--danger-soft);background:transparent;color:var(--danger);font-weight:700;padding:7px 14px;font-size:12px}
footer{position:sticky;bottom:0;margin-top:24px;border-top:1px solid var(--line);background:var(--cream);padding:14px 20px 20px}
.cta{min-height:56px;width:100%;border-radius:999px;border:0;background:var(--primary);color:#fff;font-size:17px;font-weight:800}
.cta.out{background:transparent;border:1.5px solid var(--line-strong);color:var(--ink)}
.cta[disabled]{opacity:.6}
.status{border-radius:16px;background:var(--accent-soft);color:var(--accent-fg);padding:8px 12px;font-size:14px;font-weight:700;margin-top:10px}
.scrim{position:absolute;inset:0;background:rgba(20,28,24,.55);display:flex;align-items:flex-end}
.sheet{width:100%;background:var(--paper);border-radius:28px 28px 0 0;padding:20px}
.sheet h3{font-family:'Bricolage Grotesque';font-size:22px;margin:0 0 4px}
.x{float:right;width:40px;height:40px;border-radius:999px;border:1.5px solid var(--line);background:var(--paper)}
label{font-size:13px;font-weight:700;display:block;margin-top:14px}
.hint{font-size:12px;color:var(--ink-soft);margin-top:6px}
.err{font-size:12px;color:var(--danger);margin-top:6px;font-weight:600}
.alt{text-align:center;font-size:14px;margin-top:14px}
.alt a{font-weight:800;color:var(--primary-fg)}
